const items = $input.all();
const now = new Date();

for (let i = 0; i < items.length; i++) {
  const item = items[i];

  // Tambahkan timestamp
  item.json.submitted_at = now.toLocaleString('id-ID');

  // Ambil file dari sistem dan konversi ke Base64
  if (item.binary && item.binary.Upload_CV) {
    try {
      const binaryBuffer = await this.helpers.getBinaryDataBuffer(i, 'Upload_CV');
      item.json.base64_data = binaryBuffer.toString('base64');
    } catch (error) {
      item.json.base64_data = "Gagal mengonversi file";
    }
  }
}

return items;

const items = $input.all();

for (let item of items) {
  const aiResponseText = item.json.text || ""; 

  try {
    // 1. Bersihkan backticks markdown
    let cleanJson = aiResponseText.replace(/```json|```/g, '').trim();

    // 2. JURUS PAMUNGKAS: Kalau teks terpotong dan tidak ada '}', kita tambahkan paksa!
    if (!cleanJson.endsWith('}')) {
      cleanJson += '}';
    }

    // 3. Proses parse ke JSON
    const parsedData = JSON.parse(cleanJson);

    // 4. Masukkan ke item.json (Pakai nilai default kalau AI lupa menjawab)
    item.json.ai_name = parsedData.candidate_name || "Tidak disebutkan";
    item.json.ai_exp = parsedData.years_of_experience || 0;
    item.json.ai_skills = parsedData.top_skills ? parsedData.top_skills.join(", ") : "Tidak ada skill";
    item.json.ai_summary = parsedData.summary || "Summary terpotong";
    item.json.ai_score = parsedData.score || 0;
    item.json.ai_rec = parsedData.hiring_recommendation || "Belum ada rekomendasi";

    // Hapus pesan error jika berhasil
    item.json.error = undefined;
    item.json.raw_broken_text = undefined;

  } catch (error) {
    // Jika masih gagal juga, tampilkan error
    item.json.error = "Masih gagal parsing: " + error.message;
    item.json.raw_broken_text = aiResponseText;
  }
}

return items;
